            };
            let params = if let Some(parameters) = borrowed_parameters {
                held_parameters.map_or(
                    CallParameters::Borrowed(parameters),
                    CallParameters::Held,
                )
            } else {
                intrinsic_parameters.unwrap_or(CallParameters::Owned(params))
            };
